pub fn db_nth(mut xs: List<i64>, mut i: i64) -> i64 {
    loop {
        if null_p(xs) {
            return 0i64;
        } else if i64_eq(i, 0i64) {
            return car(xs);
        } else {
            (xs, i) = (cdr(xs), i64_minus(i, 1i64));
            continue;
        }
    }
}

/// `xs`, each of durability `i` up to `d` made `r`.
pub fn bumped(xs: List<i64>, d: i64, r: i64, i: i64) -> List<i64> {
    if null_p(xs) {
        nil::<i64>()
    } else {
        kayak_rt::heap_cons(if i64_lt_eq(i, d) {
            r
        } else {
            car(xs)
        }, bumped(cdr(xs), d, r, i64_plus(i, 1i64)))
    }
}

#[inline]
pub fn zeros(n: i64) -> List<i64> {
    if i64_lt_eq(n, 0i64) {
        nil::<i64>()
    } else {
        kayak_rt::heap_cons(0i64, zeros(i64_minus(n, 1i64)))
    }
}

pub fn id_in_p(mut k: i64, mut fs: List<kayak_rt::data::DataAt<'static, Frame>>) -> bool {
    loop {
        if null_p(fs) {
            return false;
        } else if {
            let tagcase_ = car(fs);
            if Frame::__is_Frame(tagcase_) {
                let (fk, ds, du,) = Frame::__Frame(tagcase_);
                i64_eq(fk, k)
            } else { kayak_rt::data::no_variant() }
        } {
            return true;
        } else {
            fs = cdr(fs);
            continue;
        }
    }
}

